P="psql -h /tmp -p 5544 -U postgres -d t -q -t -A"
como() { printf "%s\n" "begin;" "select set_config('request.jwt.claims', '{\"sub\":\"$1\",\"role\":\"authenticated\"}', true);" "set local role authenticated;" "$2" "commit;" | $P 2>&1 | grep -v '^{"sub"'; }
